<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';
if ($config['installed']) { http_response_code(403); exit('Setup is locked. Use the application login.'); }
// First-run account creation is intentionally restricted to the machine itself.
if (!in_array($_SERVER['REMOTE_ADDR'] ?? '',['127.0.0.1','::1'],true)) { http_response_code(403); exit('Run first-time setup on localhost. See DEPLOYMENT.md for remote installation.'); }
$error=''; $done=false;
$hostingReady=true;
if(stripos($_SERVER['SERVER_SOFTWARE'] ?? '','Apache')!==false) {
    $scheme=!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS']!=='off' ? 'https' : 'http';
    $probe=curl_init($scheme.'://127.0.0.1:'.(int)($_SERVER['SERVER_PORT'] ?? 80).base_url('database/aqua_rose_db.sql'));
    curl_setopt_array($probe,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>3,CURLOPT_NOBODY=>true]);
    curl_exec($probe); $hostingReady=curl_getinfo($probe,CURLINFO_HTTP_CODE)===403; curl_close($probe);
    if(!$hostingReady) $error='Apache security rules are not active yet. Restart Apache as administrator in XAMPP, then reload this page. The included deployment guide explains the project-specific rule. Installation is blocked until the private folders return Access Denied.';
}
if ($_SERVER['REQUEST_METHOD']==='POST') {
    try {
        check_csrf();
        if(!$hostingReady) throw new AppError($error);
        if(PHP_VERSION_ID<80200 || !extension_loaded('pdo_mysql') || !extension_loaded('fileinfo') || !extension_loaded('mbstring')) throw new AppError('PHP 8.2+, PDO MySQL, Fileinfo and Mbstring are required.');
        if(!is_writable($GLOBALS['storage_path']) || !is_writable(__DIR__.'/config')) throw new AppError('The config folder and private storage directory must be writable during installation.');
        $setup=['db_host'=>text_field($_POST,'db_host',120,true),'db_port'=>(string)whole($_POST['db_port'] ?? '3306',1,65535),
            'db_name'=>text_field($_POST,'db_name',64,true),'db_user'=>text_field($_POST,'db_user',80,true),'db_pass'=>(string)($_POST['db_pass'] ?? '')];
        if (!preg_match('/^[a-zA-Z0-9_]+$/D',$setup['db_name'])) throw new AppError('Use letters, numbers and underscores for the database name.');
        $password=(string)($_POST['password'] ?? ''); Auth::password($password);
        if ($password!==($_POST['password_confirmation'] ?? '')) throw new AppError('Owner passwords do not match.');
        $username=text_field($_POST,'username',80,true);
        if (!preg_match('/^[a-zA-Z0-9_.-]{3,80}$/D',$username)) throw new AppError('Use at least 3 letters, numbers, underscores or dots for the username.');
        $pdo=Database::connect($setup,false);
        $pdo->exec('CREATE DATABASE IF NOT EXISTS `'.$setup['db_name'].'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');
        $pdo->exec('USE `'.$setup['db_name'].'`');
        if ($pdo->query('SHOW TABLES')->fetch()) throw new AppError('That database already contains tables. Choose a NEW empty database; existing data will never be overwritten.');
        $sql=file_get_contents(__DIR__.'/database/aqua_rose_db.sql');
        $pdo->exec($sql);
        $stmt=$pdo->prepare("INSERT INTO users(role,name,username,password_hash) VALUES ('OWNER',?,?,?)");
        $stmt->execute([text_field($_POST,'name',120,true),$username,password_hash($password,PASSWORD_DEFAULT)]);
        $setup+=['installed'=>true,'environment'=>'local','session_timeout'=>1800,'instance_id'=>bin2hex(random_bytes(16))];
        $contents="<?php\n// Generated by local setup. Keep private; do not commit.\nif (!defined('AQUAROSE_APP')) { http_response_code(403); exit; }\nreturn ".var_export($setup,true).";\n";
        if (file_put_contents(__DIR__.'/config/local.php',$contents,LOCK_EX)===false) throw new AppError('Database created, but config/local.php could not be saved. Follow the manual installation instructions.');
        $done=true;
    } catch (AppError $e) { $error=$e->getMessage(); }
    catch (Throwable $e) { error_log((string)$e); $error='Setup could not finish. Check the database connection and storage/application.log. If an import was partially completed, choose a fresh empty database.'; }
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aqua Rose · First-time setup</title><link rel="stylesheet" href="<?=e(base_url('assets/css/app.css'))?>"></head><body class="auth-body"><main class="setup-card"><div class="brand-mark">✦</div><span class="eyebrow">AQUA ROSE / GET STARTED</span><h1>Your station, connected.</h1><p class="muted">Secure local setup for your two-branch water station. No default passwords. No existing data replaced.</p>
<?php if ($done): ?><div class="notice success">Installation complete. Sign in with the owner account you just created.</div><a class="btn primary" href="<?=e(base_url('login.php?mode=owner'))?>">Open Aqua Rose →</a>
<?php else: if ($error): ?><div class="notice danger" role="alert"><?=e($error)?></div><?php endif; ?>
<form method="post" class="form-grid"><?=csrf_field()?><h3 class="span-2">1. Database connection</h3>
<?php foreach (['db_host'=>['Host','127.0.0.1'],'db_port'=>['Port','3306'],'db_name'=>['New database name','aqua_rose_management'],'db_user'=>['Database user','root']] as $key=>[$label,$value]): ?><label><?=e($label)?><input required name="<?=e($key)?>" value="<?=e($_POST[$key] ?? $value)?>"></label><?php endforeach; ?>
<label class="span-2">Database password<input type="password" name="db_pass" autocomplete="off"><small>Use a restricted database account on a production server.</small></label>
<h3 class="span-2">2. Create your owner account</h3><label>Full name<input required name="name" maxlength="120" value="<?=e($_POST['name'] ?? '')?>" autocomplete="name"></label><label>Username<input required name="username" value="<?=e($_POST['username'] ?? '')?>" autocomplete="username"></label>
<label>Password<input required type="password" name="password" minlength="12" maxlength="128" autocomplete="new-password"></label><label>Confirm password<input required type="password" name="password_confirmation" minlength="12" autocomplete="new-password"></label><small class="span-2">At least 12 characters, including letters and numbers. Staff accounts are created after installation.</small><button class="btn primary span-2" type="submit">Set up my station →</button></form><?php endif; ?></main></body></html>
